{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 조례상 모범납세자 성실납세증 스티커 부착 차량의 공영주차장 무료 혜택 적용 기간(기한)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제7조제1항제5호에 따르면, 모범납세자로 표창을 받은 자로서 시장 또는 국세청장이 교부한 성실납세증 표지(스티커)를 부착한 차량은 발행일로부터 1년간 주차요금을 면제받는다. 따라서 공영주차장 무료 혜택의 적용 기간은 스티커(성실납세증 표지) 발행일로부터 1년까지이다.",
          "b_ids": "주차장:제7조제1항제5호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
